#include <bits/stdc++.h>using namespace std; const int INF = 1e9; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;         vector<int> a(n);        vector<bool> freq(n + 1, false);         for (int i = 0; i < n; i++) {            cin >> a[i];            freq[a[i]] = true;        }         vector<int> dp(n + 1, INF);                 for (int i = 1; i <= n; i++) {            if (freq[i]) dp[i] = 1;        }         for (int i = 1; i <= n; i++) {            for (int d = 1; d * d <= i; d++) {                if (i % d == 0) {                    int d1 = d;                    int d2 = i / d;                     if (freq[d1] && dp[i / d1] != INF) {                        dp[i] = min(dp[i], dp[i / d1] + 1);                    }                    if (freq[d2] && dp[i / d2] != INF) {                        dp[i] = min(dp[i], dp[i / d2] + 1);                    }                }            }        }                 for (int i = 1; i <= n; i++) {            if (dp[i] == INF) cout << -1 << " ";            else cout << dp[i] << " ";        }        cout << '\n';    }     return 0;}